-- 医用版装修：home_data 和 home_default_data 必须同时写。
-- 只写 home_data 的话，后台点一次「恢复默认」就会拿 home_default_data 覆盖回去。
UPDATE eb_theme SET
  home_data         = CONVERT(FROM_BASE64('') USING utf8mb4),
  home_default_data = CONVERT(FROM_BASE64('') USING utf8mb4),
  theme_data        = '{"theme_color":"#0D9488","gradient_color":"#14B8A6","sub_color":"#0D9488","light_color":"rgba(13, 148, 136, 0.1)"}',
  theme_default_data= '{"theme_color":"#0D9488","gradient_color":"#14B8A6","sub_color":"#0D9488","light_color":"rgba(13, 148, 136, 0.1)"}',
  title = 'StorApp 健康药房',
  up_time = UNIX_TIMESTAMP()
WHERE id = 1;
SELECT CONCAT('home=', CHAR_LENGTH(home_data), ' default=', CHAR_LENGTH(home_default_data), ' same=', IF(home_data = home_default_data, 'Y', 'N')) AS r FROM eb_theme WHERE id = 1;